            per_member[n] += _cents(share)
    return {
        category: {m: format_money(c) for m, c in totals[category].items()}
        for category in sorted(totals)
    }


EXPORT_COLUMNS = ["id", "date", "payer", "description", "amount", "currency",
                  "category", "base_amount"]


def export_rows(data):
    return [[e[c] for c in EXPORT_COLUMNS] for e in data["expenses"]]
